import{_ as t,o as s,c as l,j as e,a as o}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/23-只要就职成功就算跨入“胜组”？.md","filePath":"books/xialiu-shehui/23-只要就职成功就算跨入“胜组”？.md","lastUpdated":1794732511000}'),_={name:"books/xialiu-shehui/23-只要就职成功就算跨入“胜组”？.md"};function r(n,a,i,d,p,u){return s(),l("div",null,[...a[0]||(a[0]=[e("h2",{id:"只要就职成功就算跨入-胜组",tabindex:"-1"},[o("只要就职成功就算跨入“胜组”？ "),e("a",{class:"header-anchor",href:"#只要就职成功就算跨入-胜组","aria-label":'Permalink to "只要就职成功就算跨入“胜组”？"'},"​")],-1),e("p",null,"对于男性来说，人生当中没有结婚退职这一幕，也不受《男女雇佣机会均等法》的影响，故此变化没有女性那样来得剧烈。尽管如此，由于成果主义的导入、创业者的增多、自由职业者的增多以及晚婚化等多方面因素的综合影响，迈入30岁的门槛之后，男性也同样会分化成数个不同的类型。",-1),e("p",null,"财团法人“社会经济生产性本部”每年对新进入公司的员工进行一次“劳动意识调查”。根据2005年度的该项调查结果，全体新员工中有77.1%的人认为自己在就职活动中属于“胜组”（调查对象共3910人，其中男性57%，女性43%）。",-1),e("p",null,"为什么仅仅是一次就职成功就让人觉得自己是胜利者了呢？这是因为，近年来就职情形一直就像处在冰河期一样，这样的冰河期长期化持续的结果，使得成功就职足以成为一件值得庆幸的事情，因而也助长了胜利者的意识。",-1),e("p",null,"从不同学历来看，这种“胜组意识”在大学（含大专）毕业生中的比例为84.0%，而在其他各类学校毕业生中的比例为88.9%，大学毕业生的“胜组意识”较其他人群为弱。这可能是因为大学毕业后，并不一定能够进入自己所期望的企业，在学历和就职企业之间出现的反差要大于其他人群的缘故。",-1),e("p",null,"此外，对于“在决定就职方向时，你是否想到过自己可能会成为一个无固定职业的自由打工者？”这一提问，全体被调查者中有35.6%的人回答“是”。其中，大专毕业生为44.4%，高中毕业生为43.1%，专科学校毕业生为39.6%，职业技术学校毕业生为34.0%，四年制大学毕业生为33.7%，技工学校毕业生为28.6%，研究生毕业的为25.6%，学历越低的人群中这一比例越高，与前面所述“胜组意识”有相通之处。这一数据可能说明，低学历的人群对于就职更加缺少自信，更加害怕成为一个无固定职业者，故此一旦成功就职，其安心感和满足感也更强，“胜组意识”自然也更强烈。",-1)])])}const m=t(_,[["render",r]]);export{h as __pageData,m as default};
